"""This class handles wait actions"""
import json
from selenium.webdriver.support.expected_conditions import visibility_of_element_located, presence_of_element_located
from selenium.webdriver.chrome.webdriver import WebDriver
from selenium.webdriver.support.wait import WebDriverWait
from selenium.webdriver.remote.webelement import WebElement
from selenium.webdriver.common.by import By
#from polling2 import poll_decorator as poll
from polling2 import poll_decorator, poll
from polling2 import poll as p

from selenium.common.exceptions import NoSuchElementException
from selenium.webdriver.support import expected_conditions

import logging
#logging.basicConfig(filename="C:/Projects/VSCode_squish_selenium_ws/electron_app_logging/iframe_polling.log", level=logging.INFO)

class CustomWait:
    """
    Accepts webdriver instance to implement synchronisation methods

    Attributes
    ---------

    wdriver: WebDriver
        Webdriver instance passedd through

    wait_for: WebDriverWait
        WebDriverWait instance

    Methods
    ---------

    waiting_for(selector)
        Accepts a selector and waits for it to be visible

    wait_on(request_url,request_type,request_response)
        waits until the request_url with type and response status is complete
        Decorated with polling with default at 0.5 sec interval upto 10 secs

    """
    def __init__(self,c_driver: WebDriver, driverTimeout: int = 10) -> None:
        self.wdriver=c_driver
        self.wait_with=WebDriverWait(c_driver, driverTimeout)

    def waiting_for(self,selector: str) -> WebElement:
        """
        Implements WebDriver wait_until

        Args:
            selector (str): CSS selector of element

        :Return Type:
            WebElement once it has been located and visible
        """
        return self.wait_with.until(visibility_of_element_located((By.CSS_SELECTOR,selector)))

    def waiting_for_element_in_DOM(self,selector: str) -> WebElement:
        """
        Implements WebDriver wait_until

        Args:
            selector (str): CSS selector of element

        :Return Type:
            WebElement once it has been located
        """
        return self.wait_with.until(presence_of_element_located((By.CSS_SELECTOR,selector)))

    def wait_on_poll(self,request_url: str,request_type: str,request_response: int, timeout: int):
        """
            Waits on API requests for given set of parameters.
            Default polling interval is 0.5 secs and timeout 10

            Args:
                request_url (str): API url to check
                request_type (str): Type of request (eg. XHR, document, fetch)_
                request_response (int): Status of requesr

            Returns:
                Any: True or TimeOutException Object
        """
        def wait_on(request_url,request_type,request_response) :
            # Get the performance logs from driver
            perf_log=self.wdriver.get_log("performance")

            # Filter events for Response received
            network_events = [i for i in perf_log if "Network.responseReceived" == json.loads(i["message"])["message"]\
                ["method"]]

            # Convert to dict having key as url and value as a tuple of request type and response code
            network_events_filtered = {json.loads(i["message"])["message"]["params"]["response"]["url"]:\
                (json.loads(i["message"])\
                ["message"]["params"]["type"],json.loads(i["message"])["message"]["params"]["response"]\
                    ["status"]) for i in \
                    network_events}

            # Check for args present in dict
            is_present = [True for k,v in network_events_filtered.items() if k==request_url and v[0]==request_type \
                and v[1]==request_response]

            return is_present[0]

        p(lambda : wait_on(request_url,request_type,request_response), timeout=timeout, step=0.5,ignore_exceptions=(IndexError))


    @poll_decorator(step=0.5,timeout=30,ignore_exceptions=NoSuchElementException)
    def wait_on_iframe_load(self, element_in_iframe_selector, iframe_selector="[data-e2e=workspace-iframe]", iframe_timeout=3):
        try:
            WebDriverWait(self.wdriver, timeout=iframe_timeout).until(
                expected_conditions.frame_to_be_available_and_switch_to_it((
                    By.CSS_SELECTOR, iframe_selector)))

            iframe_element = self.wdriver.find_element(By.CSS_SELECTOR, element_in_iframe_selector)
            return iframe_element
        except NoSuchElementException as e:
            # Switch away from the iframe back to the main page, ready for the next poll cycle
            self.wdriver.switch_to.default_content()
            return False


